import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, time, vec3, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, CapsuleGeometry, TorusGeometry, PlaneGeometry, PointLight, Color, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'journal-badge';

  const disposables = [];
  const primitiveHandles = [];
  const timelines = [];

  // --- Capsule body (machined-metal PBR) ---
  const capsuleRadius = 0.13;
  const capsuleLength = 0.42;
  const capsuleGeo = new CapsuleGeometry(capsuleRadius, capsuleLength, 6, 16);
  const capsuleMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
  });
  const capsule = new Mesh(capsuleGeo, capsuleMat);
  capsule.rotation.z = Math.PI / 2; // lie horizontal, badge-like
  capsule.castShadow = false;
  root.add(capsule);
  disposables.push(capsuleGeo, capsuleMat);

  // --- Accent edge-light rim (thin torus tracing the capsule silhouette) ---
  const accentPulse = uniform(1.0);
  const ringGeo = new TorusGeometry(capsuleRadius * 0.98, 0.012, 8, 32);
  const ringMat = new MeshBasicNodeMaterial({
    colorNode: vec3(
      accentPulse.mul(sin(time.mul(2.0)).mul(0.12).add(0.88))
    ).mul(vec3(
      new Color(colors.accent).r,
      new Color(colors.accent).g,
      new Color(colors.accent).b
    )),
    side: DoubleSide,
    transparent: true,
    opacity: 0.95,
  });

  const ringLeft = new Mesh(ringGeo, ringMat);
  ringLeft.position.x = -capsuleLength / 2;
  ringLeft.rotation.y = Math.PI / 2;
  root.add(ringLeft);

  const ringRight = new Mesh(ringGeo.clone(), ringMat);
  ringRight.position.x = capsuleLength / 2;
  ringRight.rotation.y = Math.PI / 2;
  root.add(ringRight);
  disposables.push(ringGeo, ringMat);

  // --- Accent rim light (local, edge-lighting the badge) ---
  const rimLight = new PointLight(new Color(colors.accent), 1.0, 1.6, 2.0);
  rimLight.position.set(0.3, 0.05, 0.35);
  root.add(rimLight);

  // --- Contact-shadow-esque backing plate to read against dark stage ---
  const backGeo = new PlaneGeometry(0.7, 0.42);
  const backMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.5,
  });
  const backPlate = new Mesh(backGeo, backMat);
  backPlate.position.z = -0.08;
  root.add(backPlate);
  disposables.push(backGeo, backMat);

  // --- GLB emblem detail (per render-mode contract; keep its own materials) ---
  let emblem = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      emblem = gltf.scene;
      emblem.scale.setScalar(0.09);
      emblem.position.set(0, 0, 0.09);
      root.add(emblem);
    }).catch(() => {});
  }

  // --- Weighted-settle entrance ---
  root.scale.setScalar(0.92);
  const entrance = gsap.timeline();
  entrance.to(root.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.35,
    ease: 'power2.out',
  }).to(root.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.55,
    ease: 'power4.out',
  });
  timelines.push(entrance);

  // --- Hover: subtle rise-in ---
  let hoverTl = null;
  const baseY = 0;
  const onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY + 0.15,
      duration: 0.3,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  };
  const onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY,
      duration: 0.3,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  };

  // --- Click: emit selection event ---
  const onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    }).to(root.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.2,
      ease: 'power2.out',
    });
    timelines.push(pressTl);
    ctx.emit('hub-journal.select', { nodeId: config.id ?? 'hub-journal-badge' });
  };

  // --- Cinematic primitives (applied verbatim per spec) ---
  const parallax = ctx.primitives['parallax-scroll'](root, { intensity: 0.4 });
  primitiveHandles.push(parallax);

  const magnetic = ctx.primitives['magnetic-cursor'](root, { radius: 1.2, strength: 0.35 });
  primitiveHandles.push(magnetic);

  root.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    click: onClick,
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill());
    entrance.kill();
    if (hoverTl) hoverTl.kill();

    primitiveHandles.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });

    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });

    root.remove(rimLight);

    if (emblem) {
      emblem.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return root;
}
